import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uniform, texture, uv, float, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color, DoubleSide } = THREE;

  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  // --- Row base panel (textured + displacement) ---
  const rowGeom = new PlaneGeometry(5.2, 1.25, 80, 24);
  const rowMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.62,
    metalness: 0.5,
    side: DoubleSide,
    transparent: true,
    opacity: 0.96,
  });

  // subtle displacement via depth map
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    rowMat.map = tex;
    rowMat.color = new Color(0xffffff);
    rowMat.needsUpdate = true;
  });
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    rowMat.displacementMap = tex;
    rowMat.displacementScale = 0.05;
    rowMat.displacementBias = -0.025;
    rowMat.needsUpdate = true;
  });

  const row = new Mesh(rowGeom, rowMat);
  row.position.set(0, 0, -0.04);
  group.add(row);

  // --- Backdrop shading strip to avoid flat void behind the row ---
  const shadeGeom = new PlaneGeometry(5.4, 1.45);
  const shadeMat = new MeshBasicNodeMaterial({ color: new Color(colors.ink), transparent: true, opacity: 0.92 });
  const shade = new Mesh(shadeGeom, shadeMat);
  shade.position.set(0, 0, -0.12);
  group.add(shade);

  // --- Contact shadow under row ---
  const shadowGeom = new PlaneGeometry(5.0, 0.3);
  const shadowMat = new MeshBasicNodeMaterial({ color: new Color(0x000000), transparent: true, opacity: 0.45 });
  const shadow = new Mesh(shadowGeom, shadowMat);
  shadow.position.set(0, -0.62, -0.08);
  group.add(shadow);

  // --- Divider (accent, thin) ---
  const divGeom = new BoxGeometry(5.0, 0.012, 0.02);
  const divMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.55,
    roughness: 0.38,
    metalness: 0.6,
  });
  const divider = new Mesh(divGeom, divMat);
  divider.position.set(0, -0.585, 0.01);
  group.add(divider);

  // --- Text content ---
  // title (display serif)
  const title = ctx.fontAtlas.createText('Heritage Tier', {
    fontSize: 0.34, color: colors.paper, align: 'left',
  });
  title.position.set(-2.3, 0.08, 0.03);
  group.add(title);

  // meta (caption mono)
  const meta = ctx.fontAtlas.createText('Billed annually  /  Atelier-serviced', {
    fontSize: 0.13, color: '#9aa0ad', align: 'left',
  });
  meta.position.set(-2.3, -0.34, 0.03);
  group.add(meta);

  // price (accent, right)
  const price = ctx.fontAtlas.createText('$240 / mo', {
    fontSize: 0.3, color: colors.accent, align: 'right', maxWidthPx: 2.4,
  });
  price.position.set(2.7, 0.0, 0.03);
  group.add(price);

  // --- Accent rim strip on right edge (the "one brightest element") ---
  const rimGeom = new BoxGeometry(0.04, 1.0, 0.02);
  const rimMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.8,
    roughness: 0.3, metalness: 0.4,
  });
  const rim = new Mesh(rimGeom, rimMat);
  rim.position.set(2.45, 0.0, 0.02);
  group.add(rim);

  // --- Cinematic primitives ---
  const primResults = [];
  try { primResults.push(ctx.primitives['parallax-scroll'](group, { intensity: 0.4 })); } catch (e) {}
  try { primResults.push(ctx.primitives['depth-rotate'](group, { maxDeg: 8 })); } catch (e) {}

  // --- Entrance: rise-in (offset y +0.4 -> 0) with weighted-settle feel ---
  const tl = gsap.timeline();
  const startX = group.position.x;
  group.position.set(startX, -0.4, 0);
  tl.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(group.scale, { x: 1.04, y: 1.04, duration: 0.45, ease: 'power2.out' }, '-=0.2');
  tl.to(group.scale, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' });

  // --- Hover (rise-in subtle 0.15) ---
  let hoverTween = null;
  let pressTween = null;

  group.userData.handlers = {
    hover: (on) => {
      if (hoverTween) hoverTween.kill();
      hoverTween = gsap.to(group.position, {
        y: on ? 0.15 : 0, duration: 0.5, ease: 'power3.out', overwrite: true,
      });
    },
    press: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.timeline();
      pressTween.to(group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
      pressTween.to(group.scale, { x: 1.0, y: 1.0, duration: 0.3, ease: 'power3.out' });
    },
    click: () => {
      ctx.emit('hub-pricing.select', { id: 'pricing-row', source: 'hub-pricing' });
    },
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    primResults.forEach((r) => r && r.cleanup && r.cleanup());
    rowGeom.dispose(); rowMat.dispose();
    shadeGeom.dispose(); shadeMat.dispose();
    shadowGeom.dispose(); shadowMat.dispose();
    divGeom.dispose(); divMat.dispose();
    rimGeom.dispose(); rimMat.dispose();
    [title, meta, price].forEach((t) => { if (t && t.geometry) t.geometry.dispose(); if (t && t.material) t.material.dispose(); });
  };

  return group;
}
